import unittest
from candidate import is_prime

class TestIsPrime(unittest.TestCase):
    def test_is_prime_negative_value_returns_false(self):
        self.assertFalse(is_prime(-10))

    def test_is_prime_zero_returns_false(self):
        self.assertFalse(is_prime(0))

    def test_is_prime_one_returns_false(self):
        self.assertFalse(is_prime(1))

    def test_is_prime_two_returns_true(self):
        self.assertTrue(is_prime(2))

    def test_is_prime_three_returns_true(self):
        self.assertTrue(is_prime(3))

    def test_is_prime_small_composite_returns_false(self):
        self.assertFalse(is_prime(4))
        self.assertFalse(is_prime(6))
        self.assertFalse(is_prime(9))

    def test_is_prime_small_prime_returns_true(self):
        self.assertTrue(is_prime(5))
        self.assertTrue(is_prime(7))
        self.assertTrue(is_prime(11))

    def test_is_prime_large_composite_returns_false(self):
        self.assertFalse(is_prime(20000))

    def test_is_prime_large_prime_returns_true(self):
        self.assertTrue(is_prime(104729))

    def test_is_prime_input_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            is_prime(None)

    def test_is_prime_input_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            is_prime("5")

    def test_is_prime_input_float_raises_type_error(self):
        with self.assertRaises(TypeError):
            is_prime(5.0)

    def test_is_prime_input_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            is_prime([5])

    def test_is_prime_return_type_is_bool(self):
        self.assertIsInstance(is_prime(2), bool)
        self.assertIsInstance(is_prime(4), bool)
        self.assertIsInstance(is_prime(104729), bool)

    def test_is_prime_even_large_composite_returns_false(self):
        self.assertFalse(is_prime(10000))

    def test_is_prime_odd_large_composite_returns_false(self):
        self.assertFalse(is_prime(99999))

    def test_is_prime_large_prime_edge_case_returns_true(self):
        self.assertTrue(is_prime(999983))

if __name__ == "__main__":
    unittest.main()
